lfs_block_t b = lfs->free.off;
lfs_block_t end = lfs->free.size;
uint32_t i = 0;

// find free block
while (true) {
    // check for free block in lookahead
    if (b >= lfs->free.size) {
        // reset lookahead
        lfs->free.off = 0;
        b = 0;
        i = 0;
    }

    // find free bit in current word
    if (b + 32 < end) {
        // search 32 bits at a time
        if ((lfs->free.lookahead & 0xffffffff) != 0xffffffff) {
            // find free bit in current word
            for (uint32_t k = 0; k < 32; k++) {
                if (!(lfs->free.lookahead & (1U << k))) {
                    *block = lfs->free.off + k;
                    lfs->free.lookahead |= 1U << k;
                    return 0;
                }
            }
        }
        b += 32;
        i += 32;
    } else {
        // check remaining bits
        uint32_t remaining = end - b;
        uint32_t mask = (1U << remaining) - 1;
        if ((lfs->free.lookahead & mask) != mask) {
            // find free bit in remaining bits
            for (uint32_t k = 0; k < remaining; k++) {
                if (!(lfs->free.lookahead & (1U << k))) {
                    *block = lfs->free.off + k;
                    lfs->free.lookahead |= 1U << k;
                    return 0;
                }
            }
        }
        break;
    }
}

// no free block found
return LFS_ERR_NOSPC;
// END_CODE

